-- Owner's wording for the channel-order SMS. Only replaces the text if it
-- is still the first default (an edited template is left alone).
UPDATE "sms_templates" SET "body_en" = 'Dear {{name}}, we have received your order {{orderNumber}} from {{channel}}. Total: ৳{{amount}}. We will send it to you soon. Thank you for choosing Amadere.com!' WHERE "key" = 'channel_order_placed' AND "body_en" = 'Dear {{name}}, we have received your order {{orderNumber}} from {{channel}}. Total: ৳{{amount}}. We will send it to you soon. Thank you for choosing Amader!';
UPDATE "sms_templates" SET "body_bn" = 'প্রিয় {{name}}, {{channel}} থেকে আপনার অর্ডার {{orderNumber}} আমরা পেয়েছি। মোট: ৳{{amount}}। শীঘ্রই আমরা এটি আপনার কাছে পাঠিয়ে দেব। Amadere.com এর সাথে থাকার জন্য ধন্যবাদ!' WHERE "key" = 'channel_order_placed' AND "body_bn" = 'প্রিয় {{name}}, {{channel}} থেকে আপনার অর্ডার {{orderNumber}} আমরা পেয়েছি। মোট: ৳{{amount}}। শীঘ্রই আমরা এটি আপনার কাছে পাঠিয়ে দেব। আমাদের সাথে থাকার জন্য ধন্যবাদ!';
